import java.util.ArrayList;
import java.util.List;

class Box<T> {
    private final List<T> items = new ArrayList<>();
    void put(T item) { items.add(item); }
    T take() { return items.isEmpty() ? null : items.remove(items.size() - 1); }
    int size() { return items.size(); }
}

public class Example {
    static <T extends Comparable<T>> T smallest(List<T> xs) {
        T best = xs.get(0);
        for (T x : xs) if (x.compareTo(best) < 0) best = x;
        return best;
    }

    public static void main(String[] args) {
        Box<String> seeds = new Box<>();
        seeds.put("maize");
        seeds.put("beans");
        String s = seeds.take();         // no cast
        System.out.println(s + ", " + seeds.size() + " left");
        // seeds.put(42);                // would not compile: the box holds Strings

        System.out.println(smallest(List.of(7, 3, 9)));
        System.out.println(smallest(List.of("rice", "beans", "maize")));
    }
}

