import java.util.List;

public class Best {
    public static <T extends Comparable<T>> T max(List<T> items) {
        if (items.isEmpty()) return null;
        T best = items.get(0);
        for (T x : items) if (x.compareTo(best) > 0) best = x;
        return best;
    }

    public static <T extends Comparable<T>> T min(List<T> items) {
        if (items.isEmpty()) return null;
        T best = items.get(0);
        for (T x : items) if (x.compareTo(best) < 0) best = x;
        return best;
    }

    public static <T> T firstOr(List<T> items, T fallback) {
        return items.isEmpty() ? fallback : items.get(0);
    }

    public static <T extends Comparable<T>> boolean isSorted(List<T> items) {
        for (int i = 1; i < items.size(); i++) {
            if (items.get(i - 1).compareTo(items.get(i)) > 0) return false;
        }
        return true;
    }
}

